type QueueItem =
  | { state: "waiting"; position: number }
  | { state: "complete"; score: number };

function unreachable(value: never): never {
  throw new Error("Unexpected queue item: " + JSON.stringify(value));
}

function describe(item: QueueItem): string {
  switch (item.state) {
    case "waiting": return "position " + item.position;
    case "complete": return "score " + item.score;
    default: return unreachable(item);
  }
}

console.log(describe({ state: "waiting", position: 2 }));

function normalize(value: string): string;
function normalize(value: readonly string[]): string[];
function normalize(value: string | readonly string[]): string | string[] {
  if (typeof value === "string") return value.trim();
  return value.map((item) => item.trim());
}

console.log(normalize("  math  ").toUpperCase());
console.log(normalize([" art ", " history "]).join(","));

