type ScoreResult =
  | { ok: true; points: number }
  | { ok: false; message: string };

function parseScore(text: string): ScoreResult {
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    return { ok: false, message: "invalid JSON" };
  }
  if (typeof data !== "object" || data === null || !("points" in data) ||
      typeof data.points !== "number" || !Number.isInteger(data.points) ||
      data.points < 0) {
    return { ok: false, message: "expected nonnegative integer points" };
  }
  return { ok: true, points: data.points };
}

for (const text of ['{"points":8}', '{"points":false}', "{"]) {
  const result = parseScore(text);
  console.log(result.ok ? "points=" + result.points : result.message);
}
